// Pointer events support mouse, pen and touch. Tap/keyboard handlers stay intact.
export function attachDragInteraction(root,onDrop,onCancel=()=>{}){
 const doc=root.ownerDocument;let drag=null,ghost=null,hover=null,suppressUntil=0;
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function clear(){ghost?.remove();ghost=null;hover?.classList.remove('drop-hover');hover=null;drag?.source.classList.remove('drag-origin');root.classList.remove('drag-active');drag=null}
 function down(e){if(drag)return;const source=e.target.closest('[data-drag]');if(root.dataset.locked==='yes'||!source||source.disabled||e.button!==0||!root.contains(source))return;drag={source,value:source.dataset.drag,id:e.pointerId,x:e.clientX,y:e.clientY,moved:false}}
 function move(e){if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<9)return;e.preventDefault();if(!drag.moved){drag.moved=true;drag.source.classList.add('drag-origin');root.classList.add('drag-active');ghost=doc.createElement('div');ghost.className='drag-ghost';ghost.setAttribute('aria-hidden','true');ghost.textContent=drag.source.dataset.dragLabel??drag.source.textContent;doc.body.append(ghost)}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';const hit=doc.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drop]');const target=hit&&root.contains(hit)&&!hit.disabled?hit:null;if(hover!==target){hover?.classList.remove('drop-hover');hover=target;hover?.classList.add('drop-hover')}}
 function up(e){if(!drag||e.pointerId!==drag.id)return;const d=drag;if(d.moved){e.preventDefault();suppressUntil=performance.now()+450;const target=hover?.dataset.drop;const dropBox=hover?.getBoundingClientRect();clear();if(target!==undefined){onDrop({type:'drop',value:d.value,target});}else{onCancel();root.classList.add('drop-return');setTimeout(()=>root.classList.remove('drop-return'),400)}}else clear()}
 function cancel(){clear()}
 function blockClick(e){if(performance.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation();suppressUntil=0}}
 doc.defaultView.addEventListener('blur',cancel);root.addEventListener('pointerdown',down);doc.addEventListener('pointermove',move,{passive:false});doc.addEventListener('pointerup',up);doc.addEventListener('pointercancel',cancel);doc.addEventListener('click',blockClick,true);
 return ()=>{clear();doc.defaultView.removeEventListener('blur',cancel);root.removeEventListener('pointerdown',down);doc.removeEventListener('pointermove',move);doc.removeEventListener('pointerup',up);doc.removeEventListener('pointercancel',cancel);doc.removeEventListener('click',blockClick,true)};
}
export function sparkle(root){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const scene=root.querySelector('.mini-scene');if(!scene)return;const layer=document.createElement('div');layer.className='sparkle-layer';layer.setAttribute('aria-hidden','true');for(let i=0;i<10;i++){const dot=document.createElement('i');dot.textContent=i%3?'✦':'●';dot.style.setProperty('--x',`${(i-4.5)*30}px`);dot.style.setProperty('--y',`${-40-Math.sin(i)*60}px`);dot.style.color=['#dba65b','#81a989','#ba98be','#e19f82'][i%4];layer.append(dot)}scene.append(layer);setTimeout(()=>layer.remove(),850)}
export function makeGameSounds(enabled){let context=null;return {play(kind='good'){if(!enabled())return;try{const C=window.AudioContext??window.webkitAudioContext;if(!C)return;context??=new C();context.resume().catch(()=>{});const now=context.currentTime;const frequencies=kind==='good'?[523,659,784]:kind==='pop'?[480,720]:kind==='drop'?[390,520]:[330];frequencies.forEach((f,i)=>{const osc=context.createOscillator(),gain=context.createGain();osc.type='sine';osc.frequency.setValueAtTime(f,now+i*.075);gain.gain.setValueAtTime(0,now+i*.075);gain.gain.linearRampToValueAtTime(.045,now+i*.075+.015);gain.gain.exponentialRampToValueAtTime(.001,now+i*.075+.17);osc.connect(gain);gain.connect(context.destination);osc.start(now+i*.075);osc.stop(now+i*.075+.18)})}catch{}},close(){context?.close().catch(()=>{});context=null}}}
